<?php

namespace Database\Seeders;

use App\Models\Act;
use App\Models\ActivityLog;
use App\Models\AiRequest;
use App\Models\Character;
use App\Models\ChecklistItem;
use App\Models\ChecklistSection;
use App\Models\Document;
use App\Models\Location;
use App\Models\Project;
use App\Models\Prop;
use App\Models\Scene;
use App\Models\Shot;
use App\Models\User;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use RuntimeException;

class ScreenplayV1Seeder extends Seeder
{
    public function run(): void
    {
        $project = Project::query()->first();
        $user = User::query()->where('is_active', true)->oldest()->first();

        if ($project === null || $user === null) {
            throw new RuntimeException('Для импорта сценария нужны карточка проекта и активный пользователь.');
        }

        DB::transaction(function () use ($project, $user): void {
            $this->removeOldStructure($project);

            $project->update([
                'duration' => '29 минут 30 секунд',
                'aspect_ratio' => '1.85:1',
                'frame_rate' => 24,
                'resolution' => '4K',
                'language' => 'Русский',
                'production_stage' => 'Постановочная разработка',
                'firefly_board_url' => 'https://firefly.adobe.com/boards/id/urn:aaid:sc:DEU1:5b89e678-b6f6-43fb-b67d-05d7064796a5',
                'camera_rules' => 'Камера в основном статична, на условной высоте собаки 120–140 см. В первом акте композиции симметричны. Первая заметная панорама — только в сцене 7, когда пёс ведёт мужчину в переулок. Камера приходит первой, ждёт персонажей и остаётся после их ухода.',
                'sound_principle' => 'Музыки нет до титров. Драматургия строится на дыхании пса, шагах, поводке, миске, бытовых шумах, дожде и тишине. После ухода пса мир становится чрезмерно громким. В титрах звучит единственная тихая старая запись с виниловым шумом.',
                'updated_by' => $user->id,
            ]);

            $characters = $this->createCharacters();
            $locations = $this->createLocations();
            $props = $this->createProps();
            $acts = $this->createActs($project);

            foreach ($this->scenes() as $sceneData) {
                $scene = Scene::create([
                    'act_id' => $acts[$sceneData['act']]->id,
                    'location_id' => $locations[$sceneData['location']]->id,
                    'assignee_id' => $user->id,
                    'code' => $sceneData['code'],
                    'number' => $sceneData['number'],
                    'title' => $sceneData['title'],
                    'action_description' => $sceneData['action'],
                    'time_of_day' => $sceneData['time'],
                    'weather' => $sceneData['weather'],
                    'costume' => $sceneData['costume'] ?? null,
                    'dialogue' => $sceneData['dialogue'] ?: null,
                    'sounds' => $sceneData['sounds'],
                    'planned_duration_seconds' => $sceneData['duration'],
                    'status' => 'Черновик',
                    'notes' => 'Сценарий 1.0. Постановочная разбивка требует утверждения.',
                ]);
                $scene->characters()->sync(collect($sceneData['characters'])->map(fn (string $name) => $characters[$name]->id));
                $scene->props()->sync(collect($sceneData['props'])->map(fn (string $name) => $props[$name]->id));

                foreach ($this->shots()[$sceneData['code']] as $index => $shotData) {
                    Shot::create([
                        'scene_id' => $scene->id,
                        'assignee_id' => $user->id,
                        'code' => $scene->code.'-K'.str_pad((string) ($index + 1), 2, '0', STR_PAD_LEFT),
                        'number' => $index + 1,
                        'description' => $shotData[0],
                        'shot_size' => $shotData[2],
                        'camera_position' => 'Высота 120–140 см, если в описании кадра не указано иное.',
                        'camera_movement' => $shotData[3],
                        'lens' => 'Мягкий винтажный рисунок; фокусное уточнить на техническом тесте.',
                        'planned_duration_seconds' => $shotData[1],
                        'sound' => $shotData[4],
                        'dialogue' => $shotData[5] ?: null,
                        'creation_method' => 'Игровая постановочная съёмка',
                        'status' => 'Черновик',
                        'notes' => 'Кадр разработан по сценарию 1.0 и подлежит режиссёрскому утверждению.',
                    ]);
                }
            }

            $this->createChecklist($project, $user);
            $this->storeScreenplayDocument($project, $user);
        });
    }

    private function removeOldStructure(Project $project): void
    {
        $types = [Act::class, Scene::class, Shot::class, Character::class, Location::class, Prop::class, ChecklistItem::class];
        DB::table('asset_links')->whereIn('linkable_type', $types)->delete();
        AiRequest::query()->whereIn('subject_type', $types)->update(['subject_type' => null, 'subject_id' => null]);
        ActivityLog::query()->whereIn('subject_type', $types)->update(['subject_type' => null, 'subject_id' => null]);
        ChecklistSection::query()->where('project_id', $project->id)->delete();
        Act::query()->where('project_id', $project->id)->delete();
        Character::query()->delete();
        Location::query()->delete();
        Prop::query()->delete();
    }

