    private function createActs(Project $project): array
    {
        $data = [1 => ['Ритуал', 'Статика и симметрия. Зритель изучает ежедневный ритуал мужчины и старого пса.', 480], 2 => ['Трещина', 'Пёс нарушает маршрут, приводит мужчину к старухе и раскрывает смысл их связи.', 720], 3 => ['Обещание', 'После ухода пса мужчина возвращается к людям и принимает нового спутника.', 570]];

        return collect($data)->mapWithKeys(fn (array $row, int $number) => [$number => Act::create(['project_id' => $project->id, 'number' => $number, 'title' => $row[0], 'description' => $row[1], 'planned_duration_seconds' => $row[2], 'sort_order' => $number, 'status' => 'Черновик'])])->all();
    }

    private function scenes(): array
    {
        return [
            $this->scene('A1-S01', 1, 1, 'Чёрный экран', 'Чёрный экран открывает фильм дыханием старого пса, миской, когтем, далёким трамваем и будильником 06:30.', 'Чёрный экран / звуковое пространство', 'Предрассветное утро', 'Звуковая темнота', 45, [], ['Будильник', 'Металлическая миска'], '', 'Дыхание, миска, коготь, трамвай, будильник.'),
            $this->scene('A1-S02', 1, 2, 'Квартира мужчины', 'Мужчина просыпается рядом с пустой половиной кровати. На кухне он кормит пса, ждёт, пока тот поднимется, машинально берёт две чашки. В прихожей рядом с его пальто висит женская куртка; мужчина пристёгивает поводок, и они уходят.', 'Квартира мужчины', 'Утро', 'Серый утренний свет', 145, ['Мужчина', 'Старый пёс'], ['Будильник', 'Металлическая миска', 'Корм', 'Кофеварка', 'Две чашки', 'Женская куртка', 'Кожаный поводок', 'Карабин', 'Ошейник старого пса'], '', 'Будильник, гранулы, дыхание, пар кофеварки, карабин, дверь.'),
