            $this->scene('A2-S06', 2, 6, 'У входа в переулок', 'Вечером пёс впервые останавливается у переулка. Мужчина тянет его по старому маршруту; камера остаётся и слышит далёкий лай.', 'Вход в переулок', 'Вечер', 'После дождя', 80, ['Мужчина', 'Старый пёс'], ['Кожаный поводок', 'Карабин', 'Ошейник старого пса'], 'Мужчина: «Идём».', 'Поводок, карабин, пауза, далёкий лай.'),
