            $this->scene('A2-S10', 2, 10, 'Новый маршрут', 'На перекрёстке мужчина впервые сам выбирает новую дорогу к парку. Дома снимает ошейник и позволяет звонку сестры завершиться, не отклоняя его.', 'Перекрёсток и квартира', 'День', 'Пасмурно', 55, ['Мужчина', 'Старый пёс', 'Сестра'], ['Кожаный поводок', 'Ошейник старого пса', 'Телефон'], 'Мужчина: «Хорошо».', 'Шаги, поводок, вибрация телефона.'),
            $this->scene('A2-S11', 2, 11, 'Последние дни', 'Мужчина и пёс посещают парк, озеро, булочную и лужу. Мужчина вспоминает жену, благодарит булочника и переносит ослабевшего пса через воду, признавая, что пёс водил его.', 'Город последних дней', 'Утро — день — вечер', 'Мокро, пасмурно', 180, ['Мужчина', 'Старый пёс', 'Булочник'], ['Кожаный поводок', 'Бумажный пакет', 'Кость'], 'Мужчина: «Помнишь? Ты тогда прыгнул. В ноябре. Она смеялась. Спасибо. Я думал, это я тебя водил. Дурак. Это ты меня водил». Булочник: «Держись, старик».', 'Трава, вода, ветер, булочная, лужа, дыхание пса.'),
            $this->scene('A2-S12', 2, 12, 'Разрешение', 'На знакомой лавке мужчина гладит седую морду пса и разрешает ему уйти. Пёс закрывает глаза; вода неподвижна.', 'Набережная', 'Вечер', 'Серое небо', 40, ['Мужчина', 'Старый пёс'], [], 'Мужчина: «Хорошо. Можно».', 'Вода, дыхание, почти полная тишина.'),
            $this->scene('A3-S13', 3, 13, 'Пустая миска', 'Утром больше нет собачьего дыхания. Мужчина по привычке насыпает корм, видит пустое одеяло и садится рядом, положив ладонь на вмятину.', 'Квартира мужчины', 'Утро', 'Холодный свет', 100, ['Мужчина'], ['Будильник', 'Металлическая миска', 'Корм', 'Кофеварка', 'Одеяло пса'], '', 'Будильник, гранулы, кофеварка; отсутствие дыхания.'),
            $this->scene('A3-S14', 3, 14, 'Мир без пса', 'Пустой дом становится слишком громким. Мужчина берёт поводок, привычно наклоняется к отсутствующему псу и выходит один.', 'Квартира мужчины', 'Утро', 'Холодный свет', 60, ['Мужчина'], ['Чайник', 'Кожаный поводок', 'Карабин', 'Ошейник старого пса'], '', 'Дрель, чайник, холодильник, кран, удар карабина.'),
            $this->scene('A3-S15', 3, 15, 'Один на маршруте', 'Мужчина идёт один. Булочник молча оставляет пакет с костью. Мужчина отвечает на звонок сестры и обещает позвонить вечером.', 'Привычный маршрут', 'Утро', 'Туман', 110, ['Мужчина', 'Булочник', 'Сестра'], ['Кожаный поводок', 'Карабин', 'Бумажный пакет', 'Кость', 'Телефон'], 'Мужчина: «Спасибо. Да. Нет. Не разбудила. Я позвоню вечером».', 'Один рисунок шагов, пустой карабин, телефон.'),
            $this->scene('A3-S16', 3, 16, 'Ложный финал', 'На лавке мужчина находит в пакете кость и кладёт её на пустое место рядом. На развилке смотрит к переулку, но идёт домой.', 'Набережная', 'Утро', 'Туман', 100, ['Мужчина'], ['Бумажный пакет', 'Кость', 'Кожаный поводок', 'Карабин'], '', 'Вода, бумага пакета, шаги, карабин.'),
            $this->scene('A3-S17', 3, 17, 'Последний фонарь', 'В густом тумане мужчина встречает под фонарём чёрного щенка с запиской. Голос старухи говорит, что щенку нужен ритуал. Мужчина пристёгивает старый поводок, говорит «Идём домой», и два новых ритма уходят за камерой.', 'Улица у дома и последний фонарь', 'Следующее утро', 'Самый густой туман', 170, ['Мужчина', 'Чёрный щенок', 'Старуха'], ['Кожаный поводок', 'Карабин', 'Ошейник щенка', 'Записка', 'Жетон щенка'], 'Голос старухи: «Ему нужен ритуал». Мужчина: «Идём домой».', 'Одинокие шаги и карабин; затем быстрые лапы и тонкий жетон; пять секунд тишины.'),
        ];
    }

    private function scene(string $code, int $act, int $number, string $title, string $action, string $location, string $time, string $weather, int $duration, array $characters, array $props, string $dialogue, string $sounds): array
    {
        return compact('code', 'act', 'number', 'title', 'action', 'location', 'time', 'weather', 'duration', 'characters', 'props', 'dialogue', 'sounds') + ['costume' => 'Тёмная неприметная осенняя одежда мужчины; непрерывность износа и влажности обязательна.'];
    }

