            'A1-S04' => [$s('Прихожая: поводок рядом с курткой, мужчина касается рукава; рукав качается.', 30, 'Средний / предметный', 'Статика', 'Миска скребёт по полу.'), $s('Кухня: чашка с трещиной уходит глубже в шкаф; три секунды тишины и хлопок возвращают комнату.', 30, 'Средний / крупный', 'Статика', 'Тишина, хлопок, холодильник, батарея, дыхание.')],
            'A1-S05' => [$s('Будильник 06:30 в разные утра.', 10, 'Крупный'), $s('Корм падает в металлическую миску в 07:00.', 10, 'Крупный', 'Статика', 'Гранулы по металлу.'), $s('Карабин защёлкивается в 07:30.', 10, 'Крупный', 'Статика', 'Щелчок карабина.'), $s('Повтор улицы: мужчина и пёс по центру.', 10, 'Дальний общий', 'Статика', 'Шаги и лапы.'), $s('Булочник поднимает руку за стеклом.', 10, 'Общий'), $s('Пёс всё дольше встаёт и отстаёт; мужчина останавливается и ждёт.', 10, 'Общий'), $s('У тёмного переулка пёс поворачивает голову; поводок на миг натягивается.', 10, 'Общий / средний', 'Статика', 'Первый сбой ритма.')],
            'A2-S06' => [$s('После дождя мужчина и пёс входят в привычную композицию и подходят к переулку.', 25, 'Дальний общий'), $s('Пёс садится, мужчина тянет поводок и тихо говорит; долгая пауза.', 40, 'Общий / средний', 'Статика', 'Скрип кожи, карабин.', '«Идём». '), $s('Они уходят старым маршрутом; камера остаётся у пустого переулка.', 15, 'Общий', 'Статика', 'Далёкий лай.')],
            'A2-S07' => [$s('Симметричное приближение к переулку; пёс смещается с центра и садится.', 30, 'Дальний общий'), $s('Натянутый поводок прямой линией; мужчина повышает голос, затем выдыхает и ослабляет руку.', 30, 'Общий / средний', 'Статика', 'Кожа, дыхание.', '«Идём. Я сказал — идём». '), $s('Первая в фильме медленная панорама от мужчины и пса к узкому переулку.', 25, 'Общий', 'Медленная панорама 15–20 секунд', 'Городской звук меняется на гул переулка.'), $s('Пёс делает первый шаг в переулок; мужчина следует за ним.', 15, 'Общий', 'Осторожное завершение панорамы', 'Шаги и лапы.')],
            'A2-S08' => [$s('Гулкий переулок: пёс впереди, мужчина оглядывается на светлый выход.', 25, 'Дальний общий', 'Статика', 'Эхо шагов и лап.'), $s('Закрытые ворота и заброшенные окна проходят вокруг героев; направление задаёт пёс.', 25, 'Общий', 'Статика', 'Эхо, далёкие собаки.'), $s('Старая калитка: за ней миски и дыхание; пёс толкает створку носом.', 25, 'Средний / крупный', 'Статика', 'Миски, повизгивание, скрип калитки.')],
            'A2-S09' => [$s('Общий двор: миски, одеяла, бездомные собаки; старуха разливает воду и замечает лабрадора.', 30, 'Дальний общий', 'Статика', 'Миски, вода, собаки.', '«Пришёл всё-таки». '), $s('У калитки мужчина спрашивает о псе; лабрадор сам кладёт морду в ладонь старухи.', 30, 'Общий / средний', 'Статика', 'Дыхание.', '«Вы его знаете?» — «Теперь знаю». '), $s('Старуха ощупывает шею и бок; разговор об усталости и скором уходе.', 35, 'Средний', 'Статика', 'Два дыхания.', '«Он просто устал». — «Да. Он знает, что ему пора». '), $s('Стена старых ошейников и реакция мужчины.', 25, 'Предметный / средний', 'Статика', 'Тихий двор.', '«Ищут место, где их будут помнить». '), $s('Пёс ложится; мужчина поправляет ошейник и говорит, что смотрит за ним.', 30, 'Средний', 'Статика', 'Шерсть, ошейник.', '«Я за ним смотрю». '), $s('На словах старухи звук двора исчезает; взгляд пса и единственная слеза мужчины.', 25, 'Крупный', 'Статика', 'Только два дыхания.', '«Нет. Это он за вами смотрит». '), $s('Старуха ставит перед псом воду; пауза завершает сцену.', 15, 'Средний', 'Статика', 'Вода в миске.', '«Не торопите его». ')],
            'A2-S10' => [$s('Выход из переулка и развилка: мужчина выбирает дорогу налево к парку; пёс принимает выбор.', 25, 'Общий', 'Статика', 'Улица, шаги.', '«Хорошо». '), $s('Дома мужчина снимает ошейник, касается шеи пса и не отклоняет новый звонок сестры.', 30, 'Средний / крупный', 'Статика', 'Вибрация телефона, дыхание.')],
            'A2-S11' => [$s('Парк: пёс долго нюхает мокрое дерево, мужчина не смотрит на часы.', 25, 'Общий', 'Статика', 'Трава, ветер.', '«Помнишь?»'), $s('Озеро: мужчина садится на влажную землю, вспоминает ноябрь и смех жены, кладёт ладонь на спину пса.', 40, 'Общий / средний', 'Статика', 'Вода, ветер.', '«Ты тогда прыгнул. В ноябре. Она смеялась». '), $s('Булочная: пёс не берёт кость; булочник кладёт её у лап, мужчина впервые благодарит.', 30, 'Средний', 'Статика', 'Пакет, улица.', '«Держись, старик». — «Спасибо». '), $s('У лужи задняя лапа пса подгибается; мужчина снимает поводок и поднимает его.', 45, 'Общий / средний', 'Осторожное сопровождение', 'Вода, усилившееся дыхание.'), $s('Посреди лужи пёс кладёт морду мужчине на плечо; признание и выход на сухую брусчатку.', 40, 'Средний / крупный', 'Осторожное сопровождение', 'Вода, два дыхания.', '«Я думал, это я тебя водил. Дурак. Это ты меня водил». ')],
            'A2-S12' => [$s('Знакомая лавка: пёс лежит головой на колене, мужчина гладит седую морду.', 20, 'Общий / средний', 'Статика', 'Вода, дыхание.', '«Хорошо». '), $s('Крупно рука и закрывающиеся глаза пса.', 15, 'Крупный', 'Статика', 'Почти тишина.', '«Можно». '), $s('Неподвижная вода; затемнение.', 5, 'Общий', 'Статика', 'Тишина.')],
            'A3-S13' => [$s('Спальня: 06:30, мужчина открывает глаза; отсутствует привычное дыхание.', 25, 'Общий', 'Статика', 'Будильник и пустота.'), $s('Кухня: автоматический корм в миску и запуск кофеварки; ожидание.', 30, 'Общий / средний', 'Статика', 'Гранулы, кофеварка.'), $s('Полная миска и пустое одеяло с чёрными волосками.', 20, 'Крупный / предметный', 'Статика', 'Комнатный шум.'), $s('Мужчина выключает кофеварку, садится и кладёт ладонь на вмятину.', 15, 'Средний', 'Статика', 'Щелчок, ткань.'), $s('Часы показывают 07:30.', 10, 'Крупный', 'Статика', 'Тиканье.')],
            'A3-S14' => [$s('Пустая квартира атакует звуками: дрель, чайник, холодильник, капающий кран.', 20, 'Общий / предметный', 'Статика', 'Дрель, чайник, холодильник, кран.'), $s('Прихожая: мужчина перед пустым ошейником берёт поводок и наклоняется к отсутствующему псу.', 25, 'Общий / средний', 'Статика', 'Карабин ударяется о пряжку.'), $s('Он складывает поводок в ладони и выходит; камера остаётся.', 15, 'Общий', 'Статика', 'Одинокие шаги, дверь.')],
            'A3-S15' => [$s('Мужчина один идёт по центру улицы; сложенный поводок и пустой карабин.', 35, 'Дальний общий', 'Статика', 'Один рисунок шагов, карабин.'), $s('Булочник замечает отсутствие пса, молча оставляет пакет; мужчина возвращается и берёт его.', 35, 'Общий / средний', 'Статика', 'Бумажный пакет.', '«Спасибо». '), $s('Телефон «СЕСТРА»: мужчина отвечает и продолжает путь после разговора.', 40, 'Средний', 'Осторожное сопровождение', 'Телефон, шаги.', '«Да. Нет. Не разбудила. Я позвоню вечером». ')],
            'A3-S16' => [$s('На лавке мужчина открывает пакет, видит кость и кладёт пакет на пустое место рядом.', 40, 'Общий / средний', 'Статика', 'Бумага, вода.'), $s('Долгий взгляд на воду; мужчина встаёт.', 35, 'Общий', 'Статика', 'Вода, ветер.'), $s('Развилка: взгляд в сторону переулка, затем выбор дороги домой; ложный финал.', 25, 'Дальний общий', 'Статика', 'Шаги и карабин.')],
            'A3-S17' => [$s('Густой туман: мужчина выходит один и удаляется по центру улицы с пустым поводком.', 30, 'Дальний общий', 'Статика', 'Шаги, одинокий карабин.'), $s('Под дальним фонарём проявляется неподвижный чёрный щенок; мужчина останавливается.', 25, 'Дальний общий', 'Статика', 'Тишина тумана.'), $s('Двадцать секунд неподвижного ожидания между мужчиной и щенком.', 20, 'Общий', 'Статика', 'Едва слышное дыхание.'), $s('Мужчина подходит и приседает; щенок нюхает руку, на ошейнике видна записка.', 25, 'Средний', 'Осторожное сопровождение', 'Шаги, нюх щенка.'), $s('Записка в руках, текст не показывается; звучит голос старухи.', 15, 'Крупный / средний', 'Статика', 'Голос старухи.', '«Ему нужен ритуал». '), $s('Щенок наклоняет голову; мужчина расправляет старый поводок и защёлкивает карабин.', 20, 'Средний / крупный', 'Статика', 'Карабин, тонкий жетон.'), $s('Мужчина и щенок идут обратно к камере; новые ритмы соединяются.', 15, 'Общий', 'Осторожное сопровождение с остановкой', 'Шаги, быстрые лапы, жетон.'), $s('Щенок смотрит в объектив, затем догоняет мужчину; оба проходят за камерой.', 10, 'Средний', 'Статика', 'Лапы и шаги.', '«Идём домой». '), $s('Пустая улица остаётся после их ухода; затемнение и пять секунд полной тишины.', 10, 'Дальний общий', 'Статика', 'Удаляющиеся ритмы, затем пять секунд тишины.')],
        ];
