    private function createChecklist(Project $project, User $user): void
    {
        $sections = collect(['Сценарий 1.0', 'Персонажи', 'Локации', 'Реквизит и костюм', 'Обязательные звуки', 'Постановочная разбивка', 'Готовность к производству'])->mapWithKeys(fn (string $title, int $order) => [$title => ChecklistSection::create(['project_id' => $project->id, 'title' => $title, 'sort_order' => $order + 1])]);
        $items = [
            ['Сценарий 1.0', 'Утвердить сценарий версии 1.0', 'Зафиксировать 17 сцен и хронометраж 29:30.', 'Документ', 1],
            ['Персонажи', 'Утвердить имена и референсы персонажей', 'Мужчина, старый пёс, старуха, булочник, сестра, щенок и бездомные собаки.', 'Фото', 30],
            ['Локации', 'Выбрать город и конкретные локации', 'Квартира, маршрут, булочная, набережная, переулок, двор старухи, парк, озеро и финальная улица.', 'Фото', 25],
            ['Реквизит и костюм', 'Зафиксировать непрерывность реквизита', 'Поводок, карабин, ошейники, миска, чашки, куртка, пакет, кость, одеяло и записка.', 'Фото', 20],
            ['Обязательные звуки', 'Записать звуковую библиотеку сценария', 'Дыхание, лапы, шаги, поводок, карабин, миска, будильник, кофеварка, трамвай, дождь, вода, телефон, дрель, чайник и тишина.', 'Аудио', 20],
            ['Постановочная разбивка', 'Утвердить 69 кадров', 'Проверить длительность, крупность, движение камеры, начальный и конечный кадр каждой сцены.', 'Документ', 1],
            ['Постановочная разбивка', 'Привязать материалы к каждому кадру', 'Персонажи, костюмы, реквизит, локации и референсы должны быть связаны с кадрами.', 'Фото', 69],
            ['Готовность к производству', 'Проверить правила фильма', 'Высота камеры 120–140 см, первая панорама только в сцене 7, музыки нет до титров, смерть пса не показывается.', 'Документ', 1],
        ];
        foreach ($items as $order => $item) {
            $record = ChecklistItem::create(['section_id' => $sections[$item[0]]->id, 'assignee_id' => $user->id, 'title' => $item[1], 'description' => $item[2], 'sort_order' => $order + 1, 'completion_method' => 'Автоматически', 'status' => 'Требуются материалы']);
            $record->requirements()->create(['asset_type' => $item[3], 'label' => $item[1], 'minimum_count' => $item[4], 'recommended_count' => $item[4], 'is_required' => true, 'approved_only' => true]);
        }
    }

    private function storeScreenplayDocument(Project $project, User $user): void
    {
        $path = 'DOC/Тихий спутник — Сценарий 1.0.md';
        $content = file_get_contents(base_path($path));
        $document = Document::updateOrCreate(['project_id' => $project->id, 'title' => 'Сценарий «Тихий спутник» 1.0'], ['updated_by' => $user->id, 'type' => 'Сценарий', 'content' => $content, 'source_path' => $path, 'source_name' => 'Тихий спутник — Сценарий 1.0.md', 'version' => 1]);
        $document->versions()->updateOrCreate(['version' => 1], ['user_id' => $user->id, 'content' => $content, 'change_note' => 'Импорт утверждённого сценария версии 1.0']);
    }
}
